class CustomParserInfo(parserinfo):

    def convertyear(self, year):
        if year < 100:
            return year + 1900
        return year

class CustomParserInfo(parserinfo):

    def pertain(self, word):
        if word in ['next', 'following']:
            return 1
        elif word in ['previous', 'last']:
            return -1
        return 0

class CustomParserInfo(parserinfo):

    def validate(self, res):
        if res.year and res.year < 1900:
            return False
        return super().validate(res)

class CustomParserInfo(parserinfo):

    def convertyear(self, year, century_specified):
        return super().convertyear(year, century_specified)

class CustomParserInfo(parserinfo):

    def pertain(self, name):
        if name == 'day':
            return True
        return super().pertain(name)
